const Q_CRA64=[
  {text:"Which president signed the Civil Rights Act of 1964?",options:["John F. Kennedy","Lyndon B. Johnson","Dwight Eisenhower","Richard Nixon"],answer:1,explanation:"LBJ signed the Act on July 2, 1964, after championing it through Congress following JFK's assassination."},
  {text:"What did Title II of the Act specifically prohibit?",options:["Employment discrimination","Segregation in public accommodations","Unequal school funding","Housing discrimination"],answer:1,explanation:"Title II banned discrimination in hotels, restaurants, theaters, and other public accommodations."},
  {text:"How did Southern senators try to block the bill?",options:["They proposed amendments","They launched a filibuster","They boycotted the Senate","They challenged it in court"],answer:1,explanation:"Southern senators filibustered for 54 days — the longest in Senate history — before cloture was invoked."},
  {text:"How many Senate votes were needed to break the filibuster?",options:["A simple majority of 51","A two-thirds majority of 67","60 votes for cloture","Unanimous consent"],answer:2,explanation:"Under 1964 rules, 67 votes (two-thirds) were needed for cloture to end debate. The vote was 71-29."},
  {text:"What federal agency was created by the Civil Rights Act?",options:["The FBI Civil Rights Division","The EEOC (Equal Employment Opportunity Commission)","The Department of Education","The Civil Rights Commission"],answer:1,explanation:"Title VII created the EEOC to investigate and act on complaints of employment discrimination."},
  {text:"Which is often confused with the Civil Rights Act of 1964?",options:["The Emancipation Proclamation","The Voting Rights Act of 1965","The 13th Amendment","The Brown v. Board decision"],answer:1,explanation:"The Voting Rights Act (1965) specifically addressed voting discrimination — the 1964 Act was broader."},
  {text:"What role did JFK's assassination play in the Act's passage?",options:["It had no effect","It created momentum — LBJ framed it as JFK's legacy","It delayed the bill for years","Congress passed it before JFK died"],answer:1,explanation:"LBJ leveraged national grief to push the bill, telling Congress to honor Kennedy's memory by passing it."},
  {text:"What did the Act prohibit in employment?",options:["All hiring practices","Discrimination based on race, color, religion, sex, or national origin","Only racial discrimination","Only pay differences"],answer:1,explanation:"Title VII broadly banned employment discrimination across five protected categories."},
  {text:"How did the Senate vote on the final bill?",options:["50-50 with VP tiebreaker","60-40","73-27","Unanimous"],answer:2,explanation:"The final Senate vote was 73-27, with strong bipartisan support after the filibuster was broken."},
  {text:"What did Title VI of the Act allow the federal government to do?",options:["Create new courts","Withhold funding from discriminatory programs","Deploy troops to states","Override state constitutions"],answer:1,explanation:"Title VI gave the federal government power to cut funding to any program that practiced discrimination."},
  {text:"Which constitutional basis supported the Act's public accommodations provisions?",options:["The First Amendment","The Second Amendment","The Commerce Clause","The Tenth Amendment"],answer:2,explanation:"Congress used its power to regulate interstate commerce to justify banning discrimination in businesses."},
  {text:"What was the broader legislative agenda the Act was part of?",options:["The New Deal","The Great Society","The Fair Deal","The New Frontier"],answer:1,explanation:"The Civil Rights Act was a centerpiece of LBJ's Great Society program alongside Medicare and education reform."},
];

